local ForgeHoodFlueMaker = {}
local PRODUCTS = {
    iron_forgehoodflue = { name = "Železni napa za dim kovaške peči", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni napa za dim kovaške peči za kovace." },
    bronze_forgehoodflue = { name = "Bronast napa za dim kovaške peči", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast napa za dim kovaške peči za kovace." },
    silver_forgehoodflue = { name = "Srebrn napa za dim kovaške peči", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn napa za dim kovaške peči za kovace." },
    gilded_forgehoodflue = { name = "Pozlačen napa za dim kovaške peči", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen napa za dim kovaške peči za kovace." },
    jewel_set_forgehoodflue = { name = "Draguljast napa za dim kovaške peči", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast napa za dim kovaške peči za kovace." },
    royal_sovereign_forgehoodflue = { name = "Kraljevski suveren napa za dim kovaške peči", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren napa za dim kovaške peči z biseri za krono." },
}
local BUILDINGS = {
    forgehoodflue_workshop = { name = "Forgehoodflue delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    forgehoodflue_house = { name = "Forgehoodflue hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_forgehoodflue_atelier = { name = "Mojstrski forgehoodflue atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_forgehoodflue_palace = { name = "Suverena forgehoodflue palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
ForgeHoodFlueMaker.ironStock=14; ForgeHoodFlueMaker.bronzeStock=12; ForgeHoodFlueMaker.woodStock=14; ForgeHoodFlueMaker.leatherStock=8; ForgeHoodFlueMaker.silverStock=8; ForgeHoodFlueMaker.goldStock=6; ForgeHoodFlueMaker.jewelStock=4; ForgeHoodFlueMaker.pearlStock=4
ForgeHoodFlueMaker.productStock = {}; ForgeHoodFlueMaker.buildings = {}; ForgeHoodFlueMaker.maker = nil; ForgeHoodFlueMaker.activeMaking = {}; ForgeHoodFlueMaker.totalProducts = 0; ForgeHoodFlueMaker.dayTimer = 0
function ForgeHoodFlueMaker.init() ForgeHoodFlueMaker.ironStock=14; ForgeHoodFlueMaker.bronzeStock=12; ForgeHoodFlueMaker.woodStock=14; ForgeHoodFlueMaker.leatherStock=8; ForgeHoodFlueMaker.silverStock=8; ForgeHoodFlueMaker.goldStock=6; ForgeHoodFlueMaker.jewelStock=4; ForgeHoodFlueMaker.pearlStock=4; ForgeHoodFlueMaker.productStock={}; ForgeHoodFlueMaker.buildings={}; ForgeHoodFlueMaker.maker=nil; ForgeHoodFlueMaker.activeMaking={}; ForgeHoodFlueMaker.totalProducts=0; ForgeHoodFlueMaker.dayTimer=0; print("[ForgeHoodFlueMaker] Royal Forge Hood Flue Maker System initialized (6 products, 4 buildings)") end
function ForgeHoodFlueMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ForgeHoodFlueMaker.maker={name=n or ("Napačnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Napačnik najet: %s (spretnost: %d)",ForgeHoodFlueMaker.maker.name,s),"success") end; return true end
function ForgeHoodFlueMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ForgeHoodFlueMaker.build(id) local ok,e=ForgeHoodFlueMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ForgeHoodFlueMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ForgeHoodFlueMaker.getQualityBonus() local b=0; for _,bd in ipairs(ForgeHoodFlueMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ForgeHoodFlueMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ForgeHoodFlueMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ForgeHoodFlueMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ForgeHoodFlueMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ForgeHoodFlueMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ForgeHoodFlueMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ForgeHoodFlueMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ForgeHoodFlueMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ForgeHoodFlueMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ForgeHoodFlueMaker.buildings==0 then return false,"Potrebna napacna delavnica" end; if not ForgeHoodFlueMaker.maker then return false,"Potreben napacnik" end; return true end
function ForgeHoodFlueMaker.make(pt,qty) qty=qty or 1; local ok,e=ForgeHoodFlueMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ForgeHoodFlueMaker.ironStock=ForgeHoodFlueMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ForgeHoodFlueMaker.bronzeStock=ForgeHoodFlueMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ForgeHoodFlueMaker.woodStock=ForgeHoodFlueMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ForgeHoodFlueMaker.leatherStock=ForgeHoodFlueMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ForgeHoodFlueMaker.silverStock=ForgeHoodFlueMaker.silverStock-d.silverCost*qty end; if d.goldCost then ForgeHoodFlueMaker.goldStock=ForgeHoodFlueMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ForgeHoodFlueMaker.jewelStock=ForgeHoodFlueMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ForgeHoodFlueMaker.pearlStock=ForgeHoodFlueMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ForgeHoodFlueMaker.maker then t=math.max(1,t-math.floor(ForgeHoodFlueMaker.maker.skill/13)) end; table.insert(ForgeHoodFlueMaker.activeMaking,{id="forgehoodflue_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ForgeHoodFlueMaker.completeMaking(m) local q=1.0+(ForgeHoodFlueMaker.getQualityBonus()/100); if ForgeHoodFlueMaker.maker then q=q+(ForgeHoodFlueMaker.maker.skill/140) end; q=math.min(2.5,q); ForgeHoodFlueMaker.productStock[m.productType]=(ForgeHoodFlueMaker.productStock[m.productType] or 0)+m.quantity; ForgeHoodFlueMaker.totalProducts=ForgeHoodFlueMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ForgeHoodFlueMaker.maker then ForgeHoodFlueMaker.maker.itemsMade=ForgeHoodFlueMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ForgeHoodFlueMaker.maker.skill=math.min(100,ForgeHoodFlueMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Napa izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"forgehoodflue.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ForgeHoodFlueMaker.update(dt) if not _G.state then return end; ForgeHoodFlueMaker.dayTimer=ForgeHoodFlueMaker.dayTimer+dt; if ForgeHoodFlueMaker.dayTimer>=30 then ForgeHoodFlueMaker.dayTimer=0; for i=#ForgeHoodFlueMaker.activeMaking,1,-1 do local m=ForgeHoodFlueMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ForgeHoodFlueMaker.completeMaking(m); table.remove(ForgeHoodFlueMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ForgeHoodFlueMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ForgeHoodFlueMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ForgeHoodFlueMaker.getStats() return {ironStock=ForgeHoodFlueMaker.ironStock,bronzeStock=ForgeHoodFlueMaker.bronzeStock,woodStock=ForgeHoodFlueMaker.woodStock,leatherStock=ForgeHoodFlueMaker.leatherStock,silverStock=ForgeHoodFlueMaker.silverStock,goldStock=ForgeHoodFlueMaker.goldStock,jewelStock=ForgeHoodFlueMaker.jewelStock,pearlStock=ForgeHoodFlueMaker.pearlStock,productStock=ForgeHoodFlueMaker.productStock,numBuildings=#ForgeHoodFlueMaker.buildings,hasMaker=ForgeHoodFlueMaker.maker~=nil,makerName=ForgeHoodFlueMaker.maker and ForgeHoodFlueMaker.maker.name or "—",makerSkill=ForgeHoodFlueMaker.maker and ForgeHoodFlueMaker.maker.skill or 0,activeMaking=#ForgeHoodFlueMaker.activeMaking,totalProducts=ForgeHoodFlueMaker.totalProducts} end
return ForgeHoodFlueMaker
